{"title": "Cortex XDR endpoints - at a glance", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 2,
  "data": [
    {
      "name": "ep",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "endpoint"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "b": {
                  "terms": {
                    "field": "data.cortex.endpoint_id",
                    "size": 10000
                  },
                  "aggs": {
                    "latest": {
                      "top_hits": {
                        "size": 1,
                        "sort": [
                          {
                            "timestamp": {
                              "order": "desc"
                            }
                          }
                        ],
                        "_source": {
                          "includes": [
                            "data.cortex.endpoint_id",
                            "data.cortex.endpoint_name",
                            "data.cortex.os_type",
                            "data.cortex.endpoint_type",
                            "data.cortex.operational_status",
                            "data.cortex.endpoint_status",
                            "data.cortex.content_status",
                            "data.cortex.is_isolated",
                            "data.cortex.endpoint_version",
                            "data.cortex.assigned_prevention_policy",
                            "data.cortex.domain"
                          ]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.b.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.latest.hits.hits[0]._source.data.cortex",
          "as": "c"
        },
        {
          "type": "formula",
          "expr": "replace(datum.c.os_type + '', 'AGENT_OS_', '')",
          "as": "os"
        },
        {
          "type": "formula",
          "expr": "replace(datum.c.endpoint_type + '', 'AGENT_TYPE_', '')",
          "as": "etype"
        }
      ]
    },
    {
      "name": "unprot",
      "source": "ep",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.c.operational_status === 'UNPROTECTED'"
        }
      ]
    },
    {
      "name": "partial",
      "source": "ep",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.c.operational_status === 'PARTIALLY_PROTECTED'"
        }
      ]
    },
    {
      "name": "disc",
      "source": "ep",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.c.endpoint_status === 'DISCONNECTED'"
        }
      ]
    },
    {
      "name": "outdated",
      "source": "ep",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.c.content_status === 'OUTDATED'"
        }
      ]
    },
    {
      "name": "iso",
      "source": "ep",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.c.is_isolated === 'AGENT_ISOLATED'"
        }
      ]
    },
    {
      "name": "tiles",
      "values": [
        {
          "i": 0,
          "label": "Endpoints",
          "bad": false
        },
        {
          "i": 1,
          "label": "Unprotected",
          "bad": true
        },
        {
          "i": 2,
          "label": "Partially protected",
          "bad": true
        },
        {
          "i": 3,
          "label": "Disconnected",
          "bad": true
        },
        {
          "i": 4,
          "label": "Content outdated",
          "bad": true
        },
        {
          "i": 5,
          "label": "Isolated",
          "bad": true
        }
      ],
      "transform": [
        {
          "type": "formula",
          "expr": "datum.i === 0 ? (length(data('ep'))) : datum.i === 1 ? (length(data('unprot'))) : datum.i === 2 ? (length(data('partial'))) : datum.i === 3 ? (length(data('disc'))) : datum.i === 4 ? (length(data('outdated'))) : datum.i === 5 ? (length(data('iso'))) : 0",
          "as": "value"
        }
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.46"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "signal": "max(14, min(height * 0.42, width / 6 * 0.26))"
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "signal": "datum.bad && datum.value > 0 ? '#BD271E' : '#343741'"
          },
          "text": {
            "signal": "format(datum.value, ',')"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.82"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 12
          },
          "fill": {
            "value": "#69707D"
          },
          "text": {
            "field": "label"
          }
        }
      }
    }
  ]
}"}}

{"title": "Cortex XDR endpoints - estate", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "OS, then workstation or server, then protection state",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 4,
  "signals": [
    {
      "name": "radius",
      "update": "min(width, height) / 2 - 4"
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "endpoint"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "b": {
                  "terms": {
                    "field": "data.cortex.endpoint_id",
                    "size": 10000
                  },
                  "aggs": {
                    "latest": {
                      "top_hits": {
                        "size": 1,
                        "sort": [
                          {
                            "timestamp": {
                              "order": "desc"
                            }
                          }
                        ],
                        "_source": {
                          "includes": [
                            "data.cortex.endpoint_id",
                            "data.cortex.endpoint_name",
                            "data.cortex.os_type",
                            "data.cortex.endpoint_type",
                            "data.cortex.operational_status",
                            "data.cortex.endpoint_status",
                            "data.cortex.content_status",
                            "data.cortex.is_isolated",
                            "data.cortex.endpoint_version",
                            "data.cortex.assigned_prevention_policy",
                            "data.cortex.domain"
                          ]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.b.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.latest.hits.hits[0]._source.data.cortex",
          "as": "c"
        },
        {
          "type": "formula",
          "expr": "replace(datum.c.os_type + '', 'AGENT_OS_', '')",
          "as": "os"
        },
        {
          "type": "formula",
          "expr": "replace(datum.c.endpoint_type + '', 'AGENT_TYPE_', '')",
          "as": "etype"
        },
        {
          "type": "formula",
          "expr": "indexof([\"PROTECTED\", \"PARTIALLY_PROTECTED\", \"UNPROTECTED\"], datum.c.operational_status) >= 0 ? datum.c.operational_status : 'other'",
          "as": "prot"
        },
        {
          "type": "formula",
          "expr": "1",
          "as": "count"
        },
        {
          "type": "filter",
          "expr": "datum.count > 0"
        },
        {
          "type": "aggregate",
          "groupby": [
            "os",
            "etype",
            "prot"
          ],
          "fields": [
            "count"
          ],
          "ops": [
            "sum"
          ],
          "as": [
            "count"
          ]
        },
        {
          "type": "formula",
          "expr": "({\"PROTECTED\": \"#54B399\", \"PARTIALLY_PROTECTED\": \"#D6BF57\", \"UNPROTECTED\": \"#E7664C\", \"other\": \"#98A2B3\"})[datum.prot] || '#98A2B3'",
          "as": "prot_hex"
        },
        {
          "type": "formula",
          "expr": "indexof([\"PROTECTED\", \"PARTIALLY_PROTECTED\", \"UNPROTECTED\", \"other\"], datum.prot)",
          "as": "prot_ord"
        },
        {
          "type": "formula",
          "expr": "(datum.prot_ord < 10 ? '0' : '') + datum.prot_ord + ' ' + datum.prot",
          "as": "prot_key"
        }
      ]
    },
    {
      "name": "tree",
      "source": "raw",
      "transform": [
        {
          "type": "nest",
          "keys": [
            "os",
            "etype"
          ],
          "generate": true
        },
        {
          "type": "partition",
          "field": "count",
          "sort": {
            "field": "count",
            "order": "descending"
          },
          "size": [
            {
              "signal": "2 * PI"
            },
            {
              "signal": "radius"
            }
          ]
        }
      ]
    },
    {
      "name": "rings",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.depth > 0"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "ringc",
      "type": "ordinal",
      "domain": {
        "data": "raw",
        "field": "os"
      },
      "range": {
        "scheme": "tableau10"
      }
    },
    {
      "name": "leafc",
      "type": "ordinal",
      "domain": {
        "data": "raw",
        "field": "prot",
        "sort": {
          "op": "min",
          "field": "prot_ord"
        }
      },
      "range": {
        "data": "raw",
        "field": "prot_hex",
        "sort": {
          "op": "min",
          "field": "prot_ord"
        }
      }
    }
  ],
  "legends": [
    {
      "fill": "leafc",
      "title": null,
      "orient": "right",
      "symbolType": "circle",
      "labelLimit": 170
    }
  ],
  "marks": [
    {
      "type": "arc",
      "from": {
        "data": "rings"
      },
      "encode": {
        "enter": {
          "tooltip": {
            "signal": "datum.children ? datum.key : (datum.prot + ': ' + datum.count)"
          }
        },
        "update": {
          "x": {
            "signal": "width / 2"
          },
          "y": {
            "signal": "height / 2"
          },
          "startAngle": {
            "field": "x0"
          },
          "endAngle": {
            "field": "x1"
          },
          "innerRadius": {
            "field": "y0"
          },
          "outerRadius": {
            "field": "y1"
          },
          "stroke": {
            "value": "#fff"
          },
          "strokeWidth": {
            "value": 1.5
          },
          "fill": {
            "signal": "datum.children ? (datum.depth === 1 ? scale('ringc', datum.key) : '#CBD2DC') : scale('leafc', datum.prot)"
          },
          "fillOpacity": {
            "signal": "datum.children ? 1 : 0.95"
          }
        },
        "hover": {
          "fillOpacity": {
            "value": 0.8
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "rings"
      },
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "signal": "width / 2 + sin((datum.x0 + datum.x1) / 2) * (datum.y0 + datum.y1) / 2"
          },
          "y": {
            "signal": "height / 2 - cos((datum.x0 + datum.x1) / 2) * (datum.y0 + datum.y1) / 2"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 10
          },
          "fontWeight": {
            "signal": "datum.children ? 'bold' : 'normal'"
          },
          "fill": {
            "signal": "datum.children && datum.depth === 1 ? '#fff' : '#343741'"
          },
          "text": {
            "signal": "datum.children ? truncate(datum.key, 16) : truncate(datum.prot + '', 16)"
          },
          "opacity": {
            "signal": "(datum.x1 - datum.x0) * (datum.y0 + datum.y1) / 2 > 58 && (datum.y1 - datum.y0) > 16 ? 1 : 0"
          }
        }
      }
    }
  ]
}"}}

{"title": "Cortex XDR endpoints - connectivity", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "index": "wazuh-alerts-*",
