                          "data.cortex.assigned_prevention_policy",
                          "data.cortex.domain"
                        ]
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.scoped.b.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.latest.hits.hits[0]._source.data.cortex",
      "as": "c"
    },
    {
      "calculate": "replace(datum.c.os_type + '', 'AGENT_OS_', '')",
      "as": "os"
    },
    {
      "calculate": "replace(datum.c.endpoint_type + '', 'AGENT_TYPE_', '')",
      "as": "etype"
    },
    {
      "calculate": "indexof([\"CONNECTED\", \"DISCONNECTED\"], datum.c.endpoint_status) >= 0 ? datum.c.endpoint_status : 'other'",
      "as": "cat"
    },
    {
      "calculate": "1",
      "as": "n"
    },
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "n",
          "as": "n"
        }
      ],
      "groupby": [
        "cat"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "n",
          "as": "total"
        }
      ]
    },
    {
      "calculate": "datum.n / datum.total",
